window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Konjunktiv II and wenn-sentences · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"If I were you, I would …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"Eva's reality – Eva's wishes. Fill in: würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"She would like to be taller, though.","why":"*grösser sein*: the wish form of *sein* is **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"She would like to speak Spanish well, though.","why":"An infinitive stands at the end (*sprechen*), so the wish is **würde** + infinitive.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"She would rather work as a tour guide, though.","why":"Infinitive at the end (*arbeiten*) → **würde** + infinitive. *lieber* = rather.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"She would like to have a big flat, though.","why":"*eine Wohnung haben*: the wish form of *haben* is **hätte**. No infinitive is needed.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"What are the people thinking?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Match each picture with a phrase from the box.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"If I didn't have to work, I would be sitting in the garden now.","why":"Picture 1 shows him working, then dreaming in a deck chair. After a *wenn*-clause the main clause starts with the verb (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"If I had a car, I wouldn't have to cycle in the rain.","why":"He is cycling in the rain; a car would spare him that. *müsste* is the Konjunktiv II of *müssen*. *Velo* is Swiss for *Fahrrad*.","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"If the bus weren't late, I would be at the office on time.","why":"A late bus makes her late for work. *wäre* is the Konjunktiv II of *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Rewrite the sentences from a: start with the main clause, then the wenn-clause.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"I wouldn't have to cycle in the rain if I had a car.","why":"Main clause first, then the *wenn*-clause. In the *wenn*-clause the verb (*hätte*) goes to the end.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"I would be at the office on time if the bus weren't late.","why":"Same pattern: main clause, comma, *wenn* … verb at the end (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Fill in the words from the box. Each word is used once; the crossed-out ones are used in the example.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"I would do some things differently if I were the boss in our company.","why":"*machen* at the end → **würde** + infinitive. *Chefin sein* → **wäre**, at the end of the *wenn*-clause.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"If I were Marco, I would definitely do vocational training.","why":"*Marco sein* → **wäre** (like *Wenn ich du wäre …*). The main clause has the infinitive *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"If I could decide freely, I would work in a small company.","why":"*frei entscheiden können* → **könnte** at the end of the *wenn*-clause. Main clause with *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"If we had children, I would only have to work half days.","why":"*Kinder haben* with *wir* → **hätten**. The box leaves **müsste** for the last gap.","source":"k2","check":"*müsste* and *würde* are both correct German in b, c and e (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* is just as good). The box only says which three gaps get *würde* and which one gets *müsste*; this key is the most likely split. Ask your teacher which one the book wants."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"I have to hurry because of my work.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Rewrite the answers with weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Because my girlfriend is unpunctual.","why":"*wegen* + noun becomes *weil* + a clause with a verb; the verb (*ist*) goes to the end.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Because the weather is bad.","why":"*des schlechten Wetters* → *das Wetter ist schlecht*; after *weil* the verb goes to the end.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Because I have an important appointment.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (accusative after *haben*); verb at the end.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Fill in: wegen – weshalb – weil – deswegen – denn. A word can be used more than once.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"I can only understand him badly because of his pronunciation.","why":"A noun follows (*seiner Aussprache*, genitive), not a clause → the preposition **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Someday I'd like to travel to Italy, because I'd like to see the sea.","why":"The verb stays in 2nd place after the gap (*ich möchte*) → **denn**. With *weil* it would go to the end.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"I need to improve my listening, so I watch a lot of films.","why":"The second part is the consequence, and the verb comes right after the gap (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"My children learned German quickly because they are always with Swiss children at kindergarten.","why":"The verb is at the end (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"Why do you write the words on little cards?","why":"A question word is needed: **Weshalb** means *warum* (why)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"My sister already speaks almost fluent German, so she can help me learn German.","why":"Consequence, and the verb comes right after the gap (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"At the language course. Fill in: weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"I couldn't do the last exercise because I didn't understand it.","why":"The verb is at the end (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"There was nobody at registration, so I went back home.","why":"A new sentence that gives the consequence, with the verb right after the gap (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"Because of my good marks, I didn't have to take a test at the start of the course.","why":"A noun phrase follows (*meiner guten Noten*, genitive plural) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"There is an extra language course because a lot of people have signed up.","why":"The verb is at the end (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Unfortunately I couldn't come to the course yesterday because of my toothache.","why":"A noun phrase follows (*meiner Zahnschmerzen*, genitive plural) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"Who can find the best excuses? Choose one situation and write. The model answers are only one possibility each.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Unfortunately I couldn't tidy the kitchen, because I suddenly had bad back pain. I had to lie down. That's why I watched a film.","why":"Uses *weil* (verb at the end: *hatte*) and *Deswegen* (verb right after it: *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"Because of the flu, I didn't go to the final exam. I had a high temperature, so I stayed in bed.","why":"Uses *wegen* + genitive (*einer Grippe*) and *deswegen* + verb (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"I'm so sorry! Unfortunately I'm late, because there was an accident on the motorway. Because of the traffic jam I lost two hours.","why":"*denn* keeps the verb in 2nd place (*war*). *wegen des Staus*: genitive of *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (if-sentences, including unreal ones with Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"grammis connector dictionary: wenn (subordinating, verb at the end)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"grammis connector dictionary: weil (subordinating, verb at the end)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis connector dictionary: denn (causal, verb stays in 2nd place)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis connector dictionary: deswegen (consequence; stands before the verb or in the middle)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen with genitive)","url":"https://grammis.ids-mannheim.de/fragen/67"}]}];
